package dev.cazajefes;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
import org.bukkit.Material;
import org.bukkit.entity.EntityType;
public class RangedRaresTest {
 @Test public void twelvePowersBelongToExactlyOneWeapon(){assertEquals(12,RangedRareCatalog.ALL.size());for(Material weapon:List.of(Material.BOW,Material.CROSSBOW,Material.TRIDENT)){assertEquals(4,RangedRareCatalog.ALL.stream().filter(s->s.weapon()==weapon).count());for(var s:RangedRareCatalog.ALL){assertEquals(s.weapon()==weapon,RareCompatibility.accepts(s.id(),weapon));assertFalse(RareCompatibility.accepts(s.id(),Material.NETHERITE_SWORD));assertNotNull(RareDefinitions.get(s.id()));assertEquals(s.max(),RareDefinitions.limited(s.id(),999));}}}
 @Test public void recipesAreSeparatedByWeaponAndUseRealMaterials(){Set<String> ids=new HashSet<>();for(var s:RangedRareCatalog.ALL){assertTrue(ids.add(s.id()));assertTrue(RangedRareCatalog.MATERIALS.contains(s.material()));assertEquals(RareCompatibility.property(s.id()),RareCompatibility.recipe("crear_esencia_rare_"+s.id()));assertTrue(s.cooldown()>=8);assertFalse(s.description().isBlank());}assertEquals(6,RangedRareCatalog.MATERIALS.size());}
 @Test public void huntingMarkRequiresTwoChargedAcceptedImpacts(){assertFalse(RangedComboRules.stores("marca_cazador",true,false,400));assertFalse(RangedComboRules.trigger("marca_cazador",0,true,true,true,400,false));assertTrue(RangedComboRules.stores("marca_cazador",true,true,400));assertTrue(RangedComboRules.trigger("marca_cazador",1,true,true,true,400,false));assertFalse(RangedComboRules.trigger("marca_cazador",1,true,true,false,400,false));assertEquals(1.6,RangedRares.bonus(4),.00001);}
 @Test public void voidBoltNeedsThreeHitsThenFourthAndFrostNeedsThree(){assertFalse(RangedComboRules.trigger("cerrojo_vacio",2,true,true,true,400,false));assertTrue(RangedComboRules.trigger("cerrojo_vacio",3,true,true,true,400,false));assertFalse(RangedComboRules.trigger("estela_boreal",1,true,true,true,400,false));assertTrue(RangedComboRules.trigger("estela_boreal",2,true,true,true,400,false));}
 @Test public void anchorCannotActivateWithRepeatedThrowsAndTideNeedsAlternation(){assertFalse(RangedComboRules.trigger("ancla_abisal",1,true,true,true,20,false));assertTrue(RangedComboRules.trigger("ancla_abisal",1,true,false,false,20,false));assertFalse(RangedComboRules.trigger("ancla_abisal",0,false,false,false,20,false));assertTrue(RangedComboRules.trigger("marea_ascendente",1,false,true,true,20,false));assertFalse(RangedComboRules.trigger("marea_ascendente",1,true,true,true,20,false));}
 @Test public void healingRequiresDistanceAndShieldBreakerRequiresShield(){assertFalse(RangedComboRules.stores("pulso_retorno",true,true,143.99));assertTrue(RangedComboRules.stores("pulso_retorno",true,true,144));assertFalse(RangedComboRules.trigger("pulso_retorno",1,true,true,true,143,false));assertTrue(RangedComboRules.trigger("pulso_retorno",1,true,true,true,144,false));assertFalse(RangedComboRules.trigger("quebranto",1,true,true,true,10,false));assertTrue(RangedComboRules.trigger("quebranto",0,false,true,true,10,true));}
 @Test public void familyDropsMatchBossSpecies(){assertEquals("engranaje_umbrio",RangedRareCatalog.drop(EntityType.PILLAGER));assertEquals("polvora_resonante",RangedRareCatalog.drop(EntityType.MAGMA_CUBE));assertEquals("perla_profundidades",RangedRareCatalog.drop(EntityType.DROWNED));assertEquals("filamento_tormenta",RangedRareCatalog.drop(EntityType.EVOKER));assertNull(RangedRareCatalog.drop(EntityType.COW));for(String material:RangedRareCatalog.MATERIALS){assertFalse(RangedRareCatalog.materialName(material).isBlank());assertFalse(RangedRareCatalog.origin(material).isBlank());assertNotEquals(Material.AIR,RangedRareCatalog.materialIcon(material));}}
}
